  const fig = dr.kind === "fig" || (dr.kind === "custom" && $("input[name=cutype]:checked")?.value === "fig");
  const m = dr.mainPhoto;   // la principale (drawAltPhotos), même si une autre apparence est affichée en haut de la fiche
