const setFigCount = () => { const a = state.draft?.adjust; if (!a?.fid || !a.it) return 0;
  return a.it.with_minifigs === false ? 0 : figHave(a.it, a.it.info?.minifigs || [], a.it.quantity || 1)[a.fid] || 0; };
