  return state.items.filter(i => isHost(i) && !isFig(i) && kindOf(i.list_id) === "collection"   // (sets, sets partiels, MOC)
    && (((!i.kind || i.kind === "set") && (i.info?.minifigs || []).some(f => figKey(f.id) === k)) || (i._att || []).some(a => isFig(a) && figKey(a.number) === k)));
