  $$("input[name=figs]").forEach(r => r.checked = r.value === (it.with_minifigs ? "avec" : "sans"));
  $("#btnAcquired").hidden = true;
  $("#listLegend").textContent = "Déplacer dans la collection";
  if ($("#cfgUnbuilt")) $("#cfgUnbuilt").checked = true;
  updateEstimate();
